require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/mailer.php';if(system_is_setup()&&current_user())redirect(current_user()['role']==='resident'?'resident_portal.php':'index.php');$error=null;$submitted=false;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!rate_limit('resident-register:'.($_SERVER['REMOTE_ADDR']??'unknown'),5,900))$error='Too many applications from this address. Please try again later.';else{$full=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$username=trim($_POST['username']??'');$password=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';$age=(int)($_POST['age']??0);$address=trim($_POST['address']??'');$sector=trim($_POST['sector']??'');$household=trim($_POST['household']??'');$civil=trim($_POST['civil_status']??'Single');$contact=trim($_POST['contact_number']??'');if($full===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$username===''||strlen($password)<8||$password!==$confirm||$age<1||$address===''||$sector===''||$household==='')$error='Complete all required fields and use matching passwords with at least 8 characters.';else{$check=db()->prepare('SELECT id FROM users WHERE username=? OR email=? UNION SELECT id FROM resident_applications WHERE username=? OR email=? LIMIT 1');$check->execute([$username,$email,$username,$email]);if($check->fetch())$error='That username or email is already in use or awaiting review.';else{$pdo=db();$pdo->prepare('INSERT INTO resident_applications (full_name,email,username,password_hash,address,age,sector,household,civil_status,contact_number) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute([$full,$email,$username,password_hash($password,PASSWORD_DEFAULT),$address,$age,$sector,$household,$civil,$contact]);$id=(int)$pdo->lastInsertId();audit_action('resident_application_submitted','resident_applications',$id,$username);notify_staff('New resident account application',$full.' submitted a resident portal application.','resident_applications.php');$submitted=true;}}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Apply for resident access · Barangay Information System</title><link rel="stylesheet" href="assets/app.css"></head><body class="login-page"><main class="login-card" style="max-width:720px"><div class="brand login-brand"><div class="brand-mark"><span></span><span></span></div><div><strong>Barangay</strong><small>information system</small></div></div><div class="eyebrow">Resident portal access</div><h1>Apply for an account.</h1><p class="login-copy">Your application will be reviewed by barangay staff. Do not submit sensitive documents through this form; staff may request identity verification separately.</p><?php if($error): ?><div class="flash error"><?= h($error) ?></div><?php elseif($submitted): ?><div class="flash success">Your application was submitted for staff review. You can return to sign in after the barangay approves your account.</div><a class="primary-button full-button" href="login.php">Return to sign in</a><?php else: ?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><label>Full name<input name="full_name" required></label><label>Email<input type="email" name="email" required></label><label>Username<input name="username" required></label><label>Password<input type="password" name="password" minlength="8" required></label><label>Confirm password<input type="password" name="confirm_password" minlength="8" required></label><label>Age<input type="number" name="age" min="1" max="120" required></label><label>Contact number<input name="contact_number"></label><label class="wide">Address<input name="address" required></label><label>Sector<input name="sector" required placeholder="Youth, worker, senior citizen..."></label><label>Household<input name="household" required></label><label>Civil status<select name="civil_status"><option>Single</option><option>Married</option><option>Widowed</option><option>Separated</option></select></label><div class="form-actions wide"><a class="secondary-button" href="login.php">Cancel</a><button class="primary-button">Submit application</button></div></form><?php endif; ?></main></body></html>
